=== FILE: rtl/axil_timer.v ===
// axil_timer: AXI4-Lite timer peripheral with level interrupt.
// Implements the microarchitecture specification (prj-ada3a9b9d9.microarchitecture.a2).
// Synchronous active-low reset. One clocked process, no latches.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // State inventory (uarch section 1)
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [31:0]           rdata_q;
    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;
    reg                  expired_q;

    // Ready and handshake terms (uarch 3.1): readies depend on flops only
    wire awready = ~aw_held & ~bvalid_q;
    wire wready  = ~w_held  & ~bvalid_q;
    wire arready = ~rvalid_q;
    wire aw_fire = s_axil_awvalid & awready;
    wire w_fire  = s_axil_wvalid  & wready;
    wire ar_fire = s_axil_arvalid & arready;

    // Write join (uarch 3.2)
    wire                  wr_complete = (aw_fire | aw_held) & (w_fire | w_held);
    wire [ADDR_WIDTH-1:0] wr_addr     = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data     = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb     = w_held  ? w_strb_q  : s_axil_wstrb;

    // Address decode (uarch 4): zero-extend to 32 bits, mapped iff aligned and < 0x10
    wire [31:0] wr_addr32 = {{(32-ADDR_WIDTH){1'b0}}, wr_addr};
    wire [31:0] rd_addr32 = {{(32-ADDR_WIDTH){1'b0}}, s_axil_araddr};
    wire        wr_mapped = (wr_addr32[1:0] == 2'b00) && (wr_addr32[31:4] == 28'd0);
    wire        rd_mapped = (rd_addr32[1:0] == 2'b00) && (rd_addr32[31:4] == 28'd0);
    wire [1:0]  wr_idx    = wr_addr32[3:2];
    wire [1:0]  rd_idx    = rd_addr32[3:2];

    // Write response (uarch 3.3)
    wire [1:0] wr_resp = (!wr_mapped || (wr_idx == 2'd2)) ? RESP_SLVERR : RESP_OKAY;

    // Write strobes (uarch 5.1)
    wire wr_ok       = wr_complete && wr_mapped;
    wire wr_ctrl     = wr_ok && (wr_idx == 2'd0) && wr_strb[0];
    wire wr_load_sel = wr_ok && (wr_idx == 2'd1);
    wire wr_clr      = wr_ok && (wr_idx == 2'd3) && wr_strb[0] && wr_data[0];
    wire start       = wr_ctrl &&  wr_data[0];
    wire stop        = wr_ctrl && !wr_data[0];

    // Count-end detect (uarch 5.2): COUNT in {0,1}, all 32 bits
    wire end_evt = en_q && (count_q[31:1] == 31'd0);

    // Read mux from pre-edge flop values (uarch 3.4)
    wire [31:0] rd_value = !rd_mapped        ? 32'd0 :
                           (rd_idx == 2'd0)  ? {29'd0, mode_q, ie_q, en_q} :
                           (rd_idx == 2'd1)  ? load_q :
                           (rd_idx == 2'd2)  ? count_q :
                                               {31'd0, expired_q};
    wire [1:0]  rd_resp  = rd_mapped ? RESP_OKAY : RESP_SLVERR;

    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held   <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held    <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= 2'b00;
            rvalid_q  <= 1'b0;
            rresp_q   <= 2'b00;
            rdata_q   <= 32'd0;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
            expired_q <= 1'b0;
        end else begin
            // Write join holding registers
            if (wr_complete) begin
                aw_held <= 1'b0;
                w_held  <= 1'b0;
            end else begin
                if (aw_fire) begin
                    aw_held   <= 1'b1;
                    aw_addr_q <= s_axil_awaddr;
                end
                if (w_fire) begin
                    w_held   <= 1'b1;
                    w_data_q <= s_axil_wdata;
                    w_strb_q <= s_axil_wstrb;
                end
            end

            // B channel
            if (wr_complete) begin
                bvalid_q <= 1'b1;
                bresp_q  <= wr_resp;
            end else if (bvalid_q && s_axil_bready) begin
                bvalid_q <= 1'b0;
            end

            // R channel
            if (ar_fire) begin
                rvalid_q <= 1'b1;
                rdata_q  <= rd_value;
                rresp_q  <= rd_resp;
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q <= 1'b0;
            end

            // EN
            if (start) begin
                en_q <= 1'b1;
            end else if (stop) begin
                en_q <= 1'b0;
            end else if (end_evt && !mode_q) begin
                en_q <= 1'b0;
            end

            // IE, MODE
            if (wr_ctrl) begin
                ie_q   <= wr_data[1];
                mode_q <= wr_data[2];
            end

            // COUNT
            if (start) begin
                count_q <= load_q;
            end else if (end_evt) begin
                count_q <= mode_q ? load_q : 32'd0;
            end else if (en_q) begin
                count_q <= count_q - 32'd1;
            end

            // EXPIRED
            if (end_evt) begin
                expired_q <= 1'b1;
            end else if (wr_clr) begin
                expired_q <= 1'b0;
            end

            // LOAD byte writes
            if (wr_load_sel && wr_strb[0]) load_q[7:0]   <= wr_data[7:0];
            if (wr_load_sel && wr_strb[1]) load_q[15:8]  <= wr_data[15:8];
            if (wr_load_sel && wr_strb[2]) load_q[23:16] <= wr_data[23:16];
            if (wr_load_sel && wr_strb[3]) load_q[31:24] <= wr_data[31:24];
        end
    end

    assign s_axil_awready = awready;
    assign s_axil_wready  = wready;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;
    assign irq            = expired_q & ie_q;

endmodule
=== END FILE ===
