// Self-checking testbench for axil_timer.
// Top: tb_axil_timer. Runs tb_axil_timer_core at ADDR_WIDTH 4 and 8.
`timescale 1ns/1ps

module tb_axil_timer_core #(
    parameter integer AW = 4
) (
    input  wire        clk,
    output reg         done,
    output reg [31:0]  passed,
    output reg [31:0]  failed
);
    localparam [1:0] OK = 2'b00;
    localparam [1:0] SE = 2'b10;
    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;

    reg          aresetn;
    reg [AW-1:0] awaddr;
    reg          awvalid;
    reg [31:0]   wdata;
    reg [3:0]    wstrb;
    reg          wvalid;
    reg          bready;
    reg [AW-1:0] araddr;
    reg          arvalid;
    reg          rready;
    wire         awready, wready, bvalid, arready, rvalid, irq;
    wire [1:0]   bresp, rresp;
    wire [31:0]  rdata;

    reg [31:0]   d;
    reg [1:0]    r;
    reg          irq_eff;

    axil_timer #(.ADDR_WIDTH(AW)) dut (
        .aclk(clk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
        .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
        .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
        .irq(irq)
    );

    task chk;
        input c;
        input [8*48-1:0] m;
        begin
            if (c === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("AW=%0d check failed: %0s (t=%0t)", AW, m, $time);
            end
        end
    endtask

    task chk32;
        input [31:0] g;
        input [31:0] e;
        input [8*48-1:0] m;
        begin
            if (g === e) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("AW=%0d %0s: got 0x%h exp 0x%h (t=%0t)", AW, m, g, e, $time);
            end
        end
    endtask

    task tick;
        input integer n;
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(posedge clk); #1;
            end
        end
    endtask

    // Write: AW and W together; takes effect on first edge; B handshake on second.
    task wr;
        input [7:0]  a;
        input [31:0] dat;
        input [3:0]  s;
        input [1:0]  er;
        begin
            chk(awready && wready, "wr: readies high at start");
            awaddr = a[AW-1:0]; wdata = dat; wstrb = s;
            awvalid = 1'b1; wvalid = 1'b1;
            @(posedge clk); #1;
            awvalid = 1'b0; wvalid = 1'b0;
            irq_eff = irq;
            chk(bvalid, "wr: bvalid after completing edge");
            chk32({30'd0, bresp}, {30'd0, er}, "wr: bresp");
            bready = 1'b1;
            @(posedge clk); #1;
            bready = 1'b0;
            chk(!bvalid, "wr: bvalid low after B handshake");
        end
    endtask

    // Read: AR accepted on first edge (returns pre-edge value); R handshake on second.
    task rd;
        input [7:0] a;
        begin
            chk(arready, "rd: arready high at start");
            araddr = a[AW-1:0]; arvalid = 1'b1;
            @(posedge clk); #1;
            arvalid = 1'b0;
            chk(rvalid, "rd: rvalid after AR edge");
            d = rdata; r = rresp;
            rready = 1'b1;
            @(posedge clk); #1;
            rready = 1'b0;
            chk(!rvalid, "rd: rvalid low after R handshake");
        end
    endtask

    task rdc;
        input [7:0]  a;
        input [31:0] ed;
        input [1:0]  er;
        input [8*48-1:0] m;
        begin
            rd(a);
            chk32(d, ed, m);
            chk32({30'd0, r}, {30'd0, er}, "rresp");
        end
    endtask

    initial begin
        done = 1'b0; passed = 0; failed = 0;
        aresetn = 1'b0; awaddr = 0; awvalid = 1'b0; wdata = 0; wstrb = 0; wvalid = 1'b0;
        bready = 1'b0; araddr = 0; arvalid = 1'b0; rready = 1'b0; d = 0; r = 0; irq_eff = 1'b0;

        // ---- Reset state ----
        @(posedge clk); @(posedge clk); #1;
        chk(!bvalid && !rvalid, "reset: no responses");
        chk(awready && wready && arready, "reset: readies high");
        chk(!irq, "reset: irq low");
        aresetn = 1'b1;

        rdc(A_CTRL,   32'd0, OK, "reset CTRL");
        rdc(A_LOAD,   32'd0, OK, "reset LOAD");
        rdc(A_COUNT,  32'd0, OK, "reset COUNT");
        rdc(A_STATUS, 32'd0, OK, "reset STATUS");

        // ---- LOAD strobes ----
        wr(A_LOAD, 32'h12345678, 4'hF, OK);
        rdc(A_LOAD, 32'h12345678, OK, "LOAD full write");
        wr(A_LOAD, 32'hAABBCCDD, 4'b0101, OK);
        rdc(A_LOAD, 32'h12BB56DD, OK, "LOAD byte strobes");

        // ---- CTRL strobe and fields ----
        wr(A_CTRL, 32'h7, 4'b1110, OK);
        rdc(A_CTRL, 32'd0, OK, "CTRL ignored without wstrb0");
        rdc(A_COUNT, 32'd0, OK, "COUNT unchanged by no-strb CTRL");
        wr(A_CTRL, 32'hFFFFFFFE, 4'hF, OK);
        rdc(A_CTRL, 32'h6, OK, "CTRL IE/MODE, upper bits read 0");
        rdc(A_COUNT, 32'd0, OK, "EN=0 write leaves COUNT");
        wr(A_CTRL, 32'd0, 4'h1, OK);
        rdc(A_CTRL, 32'd0, OK, "CTRL cleared");

        // ---- COUNT write ----
        wr(A_COUNT, 32'hFFFF, 4'hF, SE);
        rdc(A_COUNT, 32'd0, OK, "COUNT write ignored");

        // ---- Unmapped ----
        wr(8'h01, 32'hFFFFFFFF, 4'hF, SE);
        wr(8'h06, 32'hFFFFFFFF, 4'hF, SE);
        wr(8'h0D, 32'h1, 4'hF, SE);
        rdc(8'h02, 32'd0, SE, "unaligned read 0x2");
        rdc(8'h05, 32'd0, SE, "unaligned read 0x5");
        rdc(8'h0F, 32'd0, SE, "unaligned read 0xF");
        rdc(A_LOAD, 32'h12BB56DD, OK, "LOAD unchanged by unmapped");
        rdc(A_CTRL, 32'd0, OK, "CTRL unchanged by unmapped");
        if (AW > 4) begin
            wr(8'h10, 32'h7, 4'hF, SE);
            wr(8'h14, 32'hDEADBEEF, 4'hF, SE);
            rdc(8'h10, 32'd0, SE, "read 0x10 unmapped");
            rdc(8'h14, 32'd0, SE, "read 0x14 unmapped");
            rdc(8'h80, 32'd0, SE, "read 0x80 unmapped");
            rdc(8'hFC, 32'd0, SE, "read 0xFC unmapped");
            rdc(A_LOAD, 32'h12BB56DD, OK, "LOAD not aliased");
            rdc(A_CTRL, 32'd0, OK, "CTRL not aliased");
        end

        // ---- One-shot count length ----
        wr(A_LOAD, 32'd5, 4'hF, OK);
        wr(A_CTRL, 32'h3, 4'h1, OK);            // start edge E; now E+1
        chk(!irq, "oneshot: irq low E+1");
        rdc(A_COUNT, 32'd4, OK, "oneshot COUNT after E+1");  // now E+3
        chk(!irq, "oneshot: irq low E+3");
        tick(1);                                 // E+4
        chk(!irq, "oneshot: irq low E+4");
        tick(1);                                 // E+5
        chk(irq, "oneshot: irq high after E+5");
        rdc(A_COUNT, 32'd0, OK, "oneshot COUNT 0 at end");
        rdc(A_CTRL, 32'h2, OK, "oneshot clears EN");
        rdc(A_STATUS, 32'h1, OK, "EXPIRED set");
        tick(5);
        rdc(A_COUNT, 32'd0, OK, "oneshot stays 0");
        chk(irq, "irq level holds");

        // ---- STATUS clear semantics ----
        wr(A_STATUS, 32'd0, 4'hF, OK);
        chk(irq, "STATUS write 0 keeps EXPIRED");
        wr(A_STATUS, 32'd1, 4'hE, OK);
        chk(irq, "STATUS without wstrb0 keeps EXPIRED");
        wr(A_STATUS, 32'd1, 4'h1, OK);
        chk(!irq_eff, "STATUS clear lowers irq after edge");
        rdc(A_STATUS, 32'd0, OK, "EXPIRED cleared");

        // ---- IE masking / late raise / lowering ----
        wr(A_CTRL, 32'h1, 4'h1, OK);            // E, LOAD=5, IE=0; now E+1
        tick(5);                                 // E+6
        chk(!irq, "IE=0 masks irq");
        rdc(A_STATUS, 32'h1, OK, "EXPIRED set with IE=0");
        wr(A_CTRL, 32'h2, 4'h1, OK);
        chk(irq_eff, "IE=1 late raises irq after edge");
        rdc(A_COUNT, 32'd0, OK, "EN=0 to EN=0 keeps COUNT");
        wr(A_CTRL, 32'h0, 4'h1, OK);
        chk(!irq_eff, "IE=0 lowers irq after edge");
        rdc(A_STATUS, 32'h1, OK, "EXPIRED kept when IE=0");
        wr(A_STATUS, 32'd1, 4'h1, OK);

        // ---- Periodic ----
        wr(A_LOAD, 32'd3, 4'hF, OK);
        wr(A_CTRL, 32'h7, 4'h1, OK);            // E; now E+1
        chk(!irq, "periodic: irq low E+1");
        tick(1);
        chk(!irq, "periodic: irq low E+2");
        tick(1);
        chk(irq, "periodic: first end E+3");
        wr(A_STATUS, 32'd1, 4'h1, OK);          // effect E+4; now E+5
        chk(!irq_eff, "periodic: cleared at E+4");
        chk(!irq, "periodic: low E+5");
        tick(1);                                 // E+6
        chk(irq, "periodic: second end E+6");
        rdc(A_CTRL, 32'h7, OK, "periodic keeps EN");        // now E+8
        rdc(A_COUNT, 32'd1, OK, "periodic COUNT after E+8"); // now E+10
        rdc(A_COUNT, 32'd2, OK, "periodic reload, after E+10"); // now E+12
        wr(A_CTRL, 32'h6, 4'h1, OK);            // stop at E+13; now E+14
        rdc(A_COUNT, 32'd2, OK, "stop edge decrements");
        rdc(A_CTRL, 32'h6, OK, "stopped CTRL");
        tick(4);
        rdc(A_COUNT, 32'd2, OK, "stopped COUNT holds");
        wr(A_STATUS, 32'd1, 4'h1, OK);
        chk(!irq_eff, "clear after stop");

        // ---- LOAD = 0 ----
        wr(A_LOAD, 32'd0, 4'hF, OK);
        wr(A_CTRL, 32'h3, 4'h1, OK);            // one-shot, IE
        chk(!irq_eff, "LOAD0: no irq after start edge");
        chk(irq, "LOAD0 oneshot ends on E+1");
        rdc(A_COUNT, 32'd0, OK, "LOAD0 COUNT 0");
        rdc(A_CTRL, 32'h2, OK, "LOAD0 oneshot clears EN");
        wr(A_STATUS, 32'd1, 4'h1, OK);
        chk(!irq_eff, "LOAD0 clear");
        wr(A_CTRL, 32'h7, 4'h1, OK);            // periodic LOAD0
        chk(irq, "LOAD0 periodic ends on E+1");
        wr(A_STATUS, 32'd1, 4'h1, OK);
        chk(irq_eff, "end beats clear");
        chk(irq, "end beats clear, irq stays");
        rdc(A_CTRL, 32'h7, OK, "LOAD0 periodic keeps EN");
        rdc(A_COUNT, 32'd0, OK, "LOAD0 periodic COUNT 0");
        wr(A_CTRL, 32'h6, 4'h1, OK);            // stop on end edge
        rdc(A_COUNT, 32'd0, OK, "LOAD0 stop COUNT 0");
        rdc(A_CTRL, 32'h6, OK, "LOAD0 stop CTRL");
        wr(A_STATUS, 32'd1, 4'h1, OK);
        chk(!irq_eff, "LOAD0 clear after stop");
        wr(A_CTRL, 32'h0, 4'h1, OK);

        // ---- Restart and restart mode ----
        wr(A_LOAD, 32'd10, 4'hF, OK);
        wr(A_CTRL, 32'h1, 4'h1, OK);            // E; now E+1
        tick(3);                                 // E+4 (COUNT 6)
        wr(A_CTRL, 32'h1, 4'h1, OK);            // restart at E+5; now E+6
        rdc(A_COUNT, 32'd9, OK, "restart reloads COUNT");  // now E+8
        wr(A_CTRL, 32'h5, 4'h1, OK);            // restart periodic at F; now F+1
        tick(9);                                 // F+10 end
        rdc(A_STATUS, 32'h1, OK, "restarted count ends at F+10"); // now F+12
        rdc(A_CTRL, 32'h5, OK, "restart applied new MODE");     // now F+14
        rdc(A_COUNT, 32'd6, OK, "periodic reload after restart");
        wr(A_CTRL, 32'h0, 4'h1, OK);
        wr(A_STATUS, 32'd1, 4'h1, OK);

        // ---- CTRL wins on end edge ----
        wr(A_LOAD, 32'd4, 4'hF, OK);
        wr(A_CTRL, 32'h1, 4'h1, OK);            // E; now E+1
        tick(2);                                 // E+3
        wr(A_CTRL, 32'h1, 4'h1, OK);            // E+4 end + restart; now E+5
        rdc(A_STATUS, 32'h1, OK, "CTRL-WINS EN=1 sets EXPIRED");  // now E+7
        rdc(A_CTRL, 32'h1, OK, "CTRL-WINS EN=1 keeps EN");        // now E+9
        rdc(A_COUNT, 32'd0, OK, "restarted oneshot ended");
        wr(A_STATUS, 32'd1, 4'h1, OK);

        wr(A_CTRL, 32'h1, 4'h1, OK);            // E; now E+1
        tick(2);
        wr(A_CTRL, 32'h0, 4'h1, OK);            // stop on oneshot end edge
        rdc(A_COUNT, 32'd0, OK, "stop on oneshot end: COUNT 0");
        rdc(A_STATUS, 32'h1, OK, "stop on oneshot end: EXPIRED");
        rdc(A_CTRL, 32'h0, OK, "stop on oneshot end: EN 0");
        wr(A_STATUS, 32'd1, 4'h1, OK);

        wr(A_CTRL, 32'h5, 4'h1, OK);            // periodic; E; now E+1
        tick(2);
        wr(A_CTRL, 32'h0, 4'h1, OK);            // stop on periodic end edge
        rdc(A_COUNT, 32'd4, OK, "stop on periodic end: COUNT=LOAD");
        tick(3);
        rdc(A_COUNT, 32'd4, OK, "stop on periodic end: held");
        rdc(A_STATUS, 32'h1, OK, "stop on periodic end: EXPIRED");
        wr(A_STATUS, 32'd1, 4'h1, OK);

        // ---- LOAD write on periodic end edge (either outcome) ----
        wr(A_CTRL, 32'h5, 4'h1, OK);            // LOAD=4; E; now E+1
        tick(2);                                 // E+3
        wr(A_LOAD, 32'd9, 4'hF, OK);            // E+4 end edge; now E+5
        rd(A_COUNT);
        chk((d === 32'd3) || (d === 32'd8), "LOAD-END-EDGE old or new");
        wr(A_CTRL, 32'h0, 4'h1, OK);
        wr(A_STATUS, 32'd1, 4'h1, OK);
        rdc(A_LOAD, 32'd9, OK, "LOAD new value kept");

        // ---- Running count undisturbed ----
        wr(A_LOAD, 32'd8, 4'hF, OK);
        wr(A_CTRL, 32'h3, 4'h1, OK);            // E; now E+1
        wr(A_COUNT, 32'h55, 4'hF, SE);          // now E+3
        rdc(A_COUNT, 32'd5, OK, "COUNT write did not disturb");  // now E+5
        wr(8'h01, 32'hFFFFFFFF, 4'hF, SE);      // now E+7
        chk(!irq, "undisturbed: not ended at E+7");
        tick(1);
        chk(irq, "undisturbed: ends on E+8");
        rdc(A_CTRL, 32'h2, OK, "undisturbed: oneshot ended");
        wr(A_STATUS, 32'd1, 4'h1, OK);

        // ---- AW before W, B back-pressure ----
        awaddr = 4; awvalid = 1'b1;
        @(posedge clk); #1;
        awvalid = 1'b0;
        chk(!awready && wready && !bvalid, "AW held, W ready");
        tick(2);
        chk(!bvalid && !awready, "still waiting for W");
        wdata = 32'h11; wstrb = 4'hF; wvalid = 1'b1;
        @(posedge clk); #1;
        wvalid = 1'b0;
        chk(bvalid && (bresp == OK), "AW-first write completes");
        chk(!awready && !wready, "readies low while bvalid");
        awaddr = 4; wdata = 32'h22; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
        rdc(A_LOAD, 32'h11, OK, "AW-first write landed");
        chk(bvalid && (bresp == OK), "B held stable under back-pressure");
        chk(!awready && !wready, "no accept during B back-pressure");
        bready = 1'b1;
        @(posedge clk); #1;
        bready = 1'b0;
        chk(!bvalid, "B released");
        chk(awready && wready, "readies back after B");
        @(posedge clk); #1;
        awvalid = 1'b0; wvalid = 1'b0;
        chk(bvalid && (bresp == OK), "held-valid write accepted");
        bready = 1'b1;
        @(posedge clk); #1;
        bready = 1'b0;
        chk(!bvalid, "second B released");
        rdc(A_LOAD, 32'h22, OK, "second write landed");

        // ---- W before AW, bready high on completing edge ----
        wdata = 32'h33; wstrb = 4'hF; wvalid = 1'b1;
        @(posedge clk); #1;
        wvalid = 1'b0;
        chk(!wready && awready && !bvalid, "W held, AW ready");
        tick(1);
        awaddr = 4; awvalid = 1'b1; bready = 1'b1;
        @(posedge clk); #1;
        awvalid = 1'b0;
        chk(bvalid && (bresp == OK), "W-first completes, bready high");
        @(posedge clk); #1;
        bready = 1'b0;
        chk(!bvalid, "W-first B released");
        rdc(A_LOAD, 32'h33, OK, "W-first write landed");

        // ---- Read with rready high on AR edge ----
        araddr = 4; arvalid = 1'b1; rready = 1'b1;
        @(posedge clk); #1;
        arvalid = 1'b0;
        chk(rvalid && (rdata == 32'h33) && (rresp == OK), "read with rready high");
        @(posedge clk); #1;
        rready = 1'b0;
        chk(!rvalid, "R released (rready high)");

        // ---- R back-pressure, COUNT stable ----
        wr(A_LOAD, 32'd100, 4'hF, OK);
        wr(A_CTRL, 32'h1, 4'h1, OK);            // E; now E+1
        araddr = 8; arvalid = 1'b1;
        @(posedge clk); #1;
        arvalid = 1'b0;
        chk(rvalid && (rdata == 32'd99), "COUNT read value");
        d = rdata;
        araddr = 12; arvalid = 1'b1;
        tick(3);
        chk(rvalid && (rdata == d) && (rresp == OK), "R stable under back-pressure");
        chk(!arready, "no AR accept while rvalid");
        rready = 1'b1;
        @(posedge clk); #1;
        rready = 1'b0;
        chk(!rvalid && arready, "R released");
        @(posedge clk); #1;
        arvalid = 1'b0;
        chk(rvalid && (rdata == 32'd0) && (rresp == OK), "held-valid read accepted");
        rready = 1'b1;
        @(posedge clk); #1;
        rready = 1'b0;
        wr(A_CTRL, 32'h0, 4'h1, OK);

        // ---- Concurrent read and write of CTRL (pre-edge read value) ----
        araddr = 0; arvalid = 1'b1;
        awaddr = 0; wdata = 32'h2; wstrb = 4'h1; awvalid = 1'b1; wvalid = 1'b1;
        @(posedge clk); #1;
        arvalid = 1'b0; awvalid = 1'b0; wvalid = 1'b0;
        chk(rvalid && (rdata == 32'd0), "read returns pre-edge CTRL");
        chk(bvalid && (bresp == OK), "concurrent write completes");
        rready = 1'b1; bready = 1'b1;
        @(posedge clk); #1;
        rready = 1'b0; bready = 1'b0;
        chk(!rvalid && !bvalid, "concurrent responses released");
        rdc(A_CTRL, 32'h2, OK, "concurrent write landed");
        wr(A_CTRL, 32'h0, 4'h1, OK);

        // ---- Mid-transfer reset ----
        wr(A_LOAD, 32'd2, 4'hF, OK);
        wr(A_CTRL, 32'h3, 4'h1, OK);            // E; now E+1
        tick(2);                                 // E+3
        chk(irq, "irq high before reset");
        awaddr = 0; awvalid = 1'b1;
        @(posedge clk); #1;
        awvalid = 1'b0;
        chk(!awready, "AW held before reset");
        araddr = 8; arvalid = 1'b1;
        @(posedge clk); #1;
        arvalid = 1'b0;
        chk(rvalid, "R pending before reset");
        aresetn = 1'b0;
        @(posedge clk); #1;
        aresetn = 1'b1;
        chk(!rvalid && !bvalid && !irq, "reset clears responses and irq");
        chk(awready && wready && arready, "reset clears held state");
        wdata = 32'h1; wstrb = 4'hF; wvalid = 1'b1;
        @(posedge clk); #1;
        wvalid = 1'b0;
        chk(!bvalid, "held AW discarded by reset");
        awaddr = 4; awvalid = 1'b1;
        @(posedge clk); #1;
        awvalid = 1'b0;
        chk(bvalid && (bresp == OK), "post-reset write completes");
        bready = 1'b1;
        @(posedge clk); #1;
        bready = 1'b0;
        rdc(A_LOAD, 32'd1, OK, "post-reset write landed");
        rdc(A_CTRL, 32'd0, OK, "CTRL reset mid-run");
        rdc(A_COUNT, 32'd0, OK, "COUNT reset mid-run");
        rdc(A_STATUS, 32'd0, OK, "STATUS reset mid-run");

        done = 1'b1;
    end
endmodule

module tb_axil_timer;
    reg clk;
    wire d4, d8;
    wire [31:0] p4, f4, p8, f8;
    reg [8*64-1:0] nonce;
    reg finished;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    tb_axil_timer_core #(.AW(4)) c4 (.clk(clk), .done(d4), .passed(p4), .failed(f4));
    tb_axil_timer_core #(.AW(8)) c8 (.clk(clk), .done(d8), .passed(p8), .failed(f8));

    initial begin
        finished = 1'b0;
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        wait (d4 && d8);
        #1;
        if (!finished) begin
            finished = 1'b1;
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, p4 + p8, f4 + f8);
            $finish;
        end
    end

    initial begin
        #1000000;
        if (!finished) begin
            finished = 1'b1;
            $error("timeout: testbench did not complete");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, p4 + p8, f4 + f8 + 1);
            $finish;
        end
    end
endmodule
